import { useState, useRef } from "react";
import cv from "@techstark/opencv-js";
import { Tensor, InferenceSession } from "onnxruntime-web";
import Loader from "./components/loader";
import CardSection from "./components/CardSection";
import { detectImage } from "./utils/detect";
import { findSimilarCards } from "./utils/clipSearch";
import { cards as allCards } from "./utils/cards";
import "./style/App.css";

const App = () => {
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState({ text: "Загрузка OpenCV.js", progress: null });
  const [image, setImage] = useState(null);
  const [clipResults, setClipResults] = useState(null);
  const [clipLoading, setClipLoading] = useState(false);
  const [clipProgress, setClipProgress] = useState(null);
  const inputImage = useRef(null);
  const imageRef = useRef(null);
  const canvasRef = useRef(null);

  const modelName = "best.onnx";
  const modelInputShape = [1, 3, 640, 640];
  const topk = 100;
  const iouThreshold = 0.45;
  const scoreThreshold = 0.25;

  cv["onRuntimeInitialized"] = async () => {
    setLoading({ text: "Загрузка модели...", progress: null });
    const yolov8 = await InferenceSession.create("./best.onnx");

    setLoading({ text: "Загрузка NMS...", progress: null });
    const nms = await InferenceSession.create("./nms-yolov8.onnx");

    setLoading({ text: "Загрузка маски...", progress: null });
    const mask = await InferenceSession.create("./mask-yolov8-seg.onnx");

    setLoading({ text: "Прогрев модели...", progress: null });
    const tensor = new Tensor(
      "float32",
      new Float32Array(modelInputShape.reduce((a, b) => a * b)),
      modelInputShape
    );
    await yolov8.run({ images: tensor });

    setSession({ net: yolov8, nms: nms, mask: mask });
    setLoading(null);
  };

  const runClip = async (boxes) => {
    if (!boxes || boxes.length === 0) return;

    setClipLoading(true);
    setClipResults(null);

    try {
      const results = {};

      for (const box of boxes) {
        const className = box.label;
        if (!allCards[className]) continue;

        const sorted = await findSimilarCards(
          imageRef.current,
          box.bounding,
          allCards[className],
          (progress) => {
            if (progress?.progress != null) {
              setClipProgress(Math.round(progress.progress));
            }
          }
        );

        // keep best result per class (highest top-1 score)
        if (
          !results[className] ||
          sorted[0]?.score > results[className][0]?.score
        ) {
          results[className] = sorted;
        }
      }

      setClipResults(results);
    } catch (e) {
      console.error("CLIP error:", e);
    } finally {
      setClipLoading(false);
      setClipProgress(null);
    }
  };

  return (
    <div className="App">
      {loading && (
        <Loader>
          {loading.progress
            ? `${loading.text} — ${loading.progress}%`
            : loading.text}
        </Loader>
      )}

      <div className="header">
        <h1>Приложение сегментации объектов YOLOv8</h1>
        <p>
          Детекция объектов в браузере на базе <code>onnxruntime-web</code>
        </p>
        <p>
          Модель: <code className="code">{modelName}</code>
        </p>
      </div>

      <div className="content">
        <img
          ref={imageRef}
          src="#"
          alt=""
          style={{ display: image ? "block" : "none" }}
          onLoad={async () => {
            const boxes = await detectImage(
              imageRef.current,
              canvasRef.current,
              session,
              topk,
              iouThreshold,
              scoreThreshold,
              modelInputShape
            );
            runClip(boxes);
          }}
        />
        <canvas
          id="canvas"
          width={modelInputShape[2]}
          height={modelInputShape[3]}
          ref={canvasRef}
        />
      </div>

      <input
        type="file"
        ref={inputImage}
        accept="image/*"
        style={{ display: "none" }}
        onChange={(e) => {
          if (image) {
            URL.revokeObjectURL(image);
            setImage(null);
            setClipResults(null);
          }
          const url = URL.createObjectURL(e.target.files[0]);
          imageRef.current.src = url;
          setImage(url);
        }}
      />

      <div className="btn-container">
        <button onClick={() => inputImage.current.click()}>
          Открыть изображение
        </button>
        {image && (
          <button
            onClick={() => {
              inputImage.current.value = "";
              imageRef.current.src = "#";
              URL.revokeObjectURL(image);
              setImage(null);
              setClipResults(null);
            }}
          >
            Закрыть изображение
          </button>
        )}
      </div>

      <CardSection
        clipResults={clipResults}
        clipLoading={clipLoading}
        clipProgress={clipProgress}
        hasImage={!!image}
      />
    </div>
  );
};

export default App;
