import { cards as allCards } from "../utils/cards";
import "../style/CardSection.css";

const CLASS_COLORS = {
  bank: "#1565C0",
  business_center: "#2E7D32",
  town_hall: "#E65100",
};

const CLASS_LABELS = {
  bank: "Банк",
  business_center: "Бизнес-центр",
  town_hall: "Мэрия",
};

const CardGroup = ({ className, sortedCards, color }) => (
  <div className="card-group">
    <div className="card-group-title" style={{ backgroundColor: color }}>
      {CLASS_LABELS[className] || className}
    </div>
    <div className="card-list">
      {sortedCards.map((card, idx) => {
        const hasScore = card.score != null;
        const isTop = hasScore && idx === 0;
        const isHighlighted = hasScore && idx < 3;
        return (
          <div
            key={card.id}
            className={`card-item ${isTop ? "top-match" : isHighlighted ? "highlighted" : ""}`}
            style={{ "--accent": color }}
          >
            {isHighlighted && (
              <div className="card-rank">{idx + 1}</div>
            )}
            <div className="card-title">{card.title}</div>
            {hasScore && (
              <div className="card-score">{(card.score * 100).toFixed(1)}%</div>
            )}
          </div>
        );
      })}
    </div>
  </div>
);

const CardSection = ({ clipResults, clipLoading, clipProgress, hasImage }) => (
  <div className="card-section">
    <h2>Карточки классов</h2>

    {clipLoading && (
      <div className="clip-loading">
        {clipProgress
          ? `Загрузка CLIP модели: ${clipProgress}%`
          : "Поиск похожих карточек..."}
      </div>
    )}

    {!hasImage && !clipResults && (
      <div className="clip-hint">
        Загрузите изображение — CLIP найдёт похожие карточки для каждого обнаруженного объекта
      </div>
    )}

    {Object.keys(allCards).map((className) => {
      const color = CLASS_COLORS[className] || "#555";
      const sorted = clipResults?.[className] ?? allCards[className];
      return (
        <CardGroup
          key={className}
          className={className}
          sortedCards={sorted}
          color={color}
        />
      );
    })}
  </div>
);

export default CardSection;
