import {
  env,
  AutoTokenizer,
  AutoProcessor,
  SiglipTextModel,
  SiglipVisionModel,
  RawImage,
} from "@huggingface/transformers";

env.allowLocalModels = false;
env.allowRemoteModels = true;

const MODEL_ID = "Xenova/siglip-base-patch16-224";
const EMBEDDING_SIZE = 768;

let tokenizer = null;
let processor = null;
let textModel = null;
let visionModel = null;
let isLoading = false;

const getModels = async (onProgress) => {
  if (tokenizer) return;
  if (isLoading) {
    await new Promise((resolve) => {
      const interval = setInterval(() => {
        if (tokenizer) { clearInterval(interval); resolve(); }
      }, 200);
    });
    return;
  }

  isLoading = true;
  const options = { device: "wasm", dtype: "q8", progress_callback: onProgress };

  tokenizer = await AutoTokenizer.from_pretrained(MODEL_ID, { progress_callback: onProgress });
  processor = await AutoProcessor.from_pretrained(MODEL_ID, { progress_callback: onProgress });
  textModel = await SiglipTextModel.from_pretrained(MODEL_ID, options);
  visionModel = await SiglipVisionModel.from_pretrained(MODEL_ID, options);
  isLoading = false;
};

const cosineSimilarity = (a, b) => {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  if (normA === 0 || normB === 0) return 0;
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
};

/**
 * Crop a bounding box from an image element into a data URL
 */
const cropImage = (imgEl, bbox) => {
  const [x, y, w, h] = bbox;
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(w, 1);
  canvas.height = Math.max(h, 1);
  const ctx = canvas.getContext("2d");

  const scaleX = imgEl.naturalWidth / imgEl.width;
  const scaleY = imgEl.naturalHeight / imgEl.height;

  ctx.drawImage(
    imgEl,
    x * scaleX, y * scaleY,
    w * scaleX, h * scaleY,
    0, 0, canvas.width, canvas.height
  );
  return canvas.toDataURL("image/jpeg");
};

/**
 * Find most similar cards for a detected object using SigLIP.
 * @param {HTMLImageElement} imgEl
 * @param {number[]} bbox [x, y, w, h]
 * @param {Array} cards list of card objects with `description` field
 * @param {Function} onProgress progress callback for model download
 * @returns cards sorted by similarity score (descending)
 */
export const findSimilarCards = async (imgEl, bbox, cards, onProgress) => {
  await getModels(onProgress);

  // encode all descriptions at once
  const descriptions = cards.map((c) => c.description);
  const textInputs = await tokenizer(descriptions, {
    padding: "max_length",
    truncation: true,
  });
  const { pooler_output: textOutput } = await textModel(textInputs);

  const textEmbeddings = cards.map((_, i) => {
    const start = i * EMBEDDING_SIZE;
    return Array.from(textOutput.data.slice(start, start + EMBEDDING_SIZE));
  });

  // encode cropped image
  const dataUrl = cropImage(imgEl, bbox);
  const image = await RawImage.read(dataUrl);
  const imageInputs = await processor(image);
  const { pooler_output: imageOutput } = await visionModel(imageInputs);
  const imageEmbedding = Array.from(imageOutput.data);

  return cards
    .map((card, i) => ({
      ...card,
      score: cosineSimilarity(imageEmbedding, textEmbeddings[i]),
    }))
    .sort((a, b) => b.score - a.score);
};
